"""Auth0 login for actions that change evidence (upload, rerun, delete).

Viewing stays open. Write endpoints depend on ``require_user``, which checks an
Auth0 access token (RS256) for the API named by AUTH0_AUDIENCE, issued by
AUTH0_DOMAIN. If Auth0 is not configured, write endpoints refuse with 503
rather than silently letting anyone in.
"""

import asyncio
import os
from dataclasses import dataclass
from typing import Any

import jwt
from fastapi import Header
from fastapi import HTTPException


@dataclass(frozen=True, slots=True)
class Settings:
    domain: str
    audience: str
    client_id: str

    @property
    def issuer(self) -> str:
        return f"https://{self.domain}/"


@dataclass(frozen=True, slots=True)
class User:
    sub: str
    claims: dict[str, Any]


_jwks: dict[str, jwt.PyJWKClient] = {}


def settings() -> Settings | None:
    domain = os.environ.get("AUTH0_DOMAIN", "").strip().removeprefix("https://")
    audience = os.environ.get("AUTH0_AUDIENCE", "").strip()
    client_id = os.environ.get("AUTH0_CLIENT_ID", "").strip()

    if not (domain and audience and client_id):
        return None

    return Settings(domain.rstrip("/"), audience, client_id)


def public_config() -> dict[str, str] | None:
    """What the browser needs to start a login (all public values)."""
    config = settings()

    if config is None:
        return None

    return {
        "domain": config.domain,
        "client_id": config.client_id,
        "audience": config.audience,
    }


def _signing_key(config: Settings, token: str) -> Any:
    client = _jwks.setdefault(
        config.domain,
        jwt.PyJWKClient(f"https://{config.domain}/.well-known/jwks.json"),
    )

    return client.get_signing_key_from_jwt(token).key


def verify(config: Settings, token: str) -> User:
    key = _signing_key(config, token)
    claims = jwt.decode(
        token,
        key,
        algorithms=["RS256"],
        audience=config.audience,
        issuer=config.issuer,
        options={"require": ["exp", "iat", "sub"]},
    )

    return User(sub=claims["sub"], claims=claims)


async def require_user(authorization: str | None = Header(default=None)) -> User:
    config = settings()

    if config is None:
        raise HTTPException(
            503, "login is not configured on this server (set AUTH0_* in .env)"
        )

    scheme, _, token = (authorization or "").partition(" ")

    if scheme.lower() != "bearer" or not token:
        raise HTTPException(
            401, "log in to do this", headers={"WWW-Authenticate": "Bearer"}
        )

    try:
        # The JWKS fetch is blocking network I/O (cached after the first call).
        return await asyncio.to_thread(verify, config, token.strip())
    except (jwt.PyJWTError, jwt.PyJWKClientError) as error:
        raise HTTPException(
            401,
            f"invalid login token: {error}",
            headers={"WWW-Authenticate": 'Bearer error="invalid_token"'},
        )
import { Auth0Provider, useAuth0 } from '@auth0/auth0-react'
import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'
import type { AuthConfig } from './types'
import { mockName } from './mock'

/** What the header needs; `enabled` is false when the server has no Auth0 config. */
export interface AuthState {
  enabled: boolean
  loading: boolean
  user: { name?: string; email?: string; picture?: string } | null
  login: () => void
  logout: () => void
}

const disabled: AuthState = { enabled: false, loading: false, user: null, login: () => {}, logout: () => {} }
const AuthContext = createContext<AuthState>(disabled)

export const useAuth = () => useContext(AuthContext)

// api.ts asks this for a token before any write (upload, rerun, delete).
let tokenSource: (() => Promise<string>) | null = null

export class LoginRedirect extends Error {
  constructor() {
    super('Taking you to the login page…')
  }
}

/** Authorization header for a write; starts a login (and throws) when logged out. */
export async function authHeaders(): Promise<Record<string, string>> {
  if (!tokenSource) return {}
  return { Authorization: `Bearer ${await tokenSource()}` }
}

const returnTo = () => location.hash || '#/'

function Bridge({ children }: { children: ReactNode }) {
  const { isAuthenticated, isLoading, user, loginWithRedirect, logout, getAccessTokenSilently } = useAuth0()

  useEffect(() => {
    tokenSource = async () => {
      if (!isAuthenticated) {
        await loginWithRedirect({ appState: { returnTo: returnTo() } })
        throw new LoginRedirect()
      }
      const token = await getAccessTokenSilently()
      if (!token) throw new Error('no access token from Auth0')
      return token
    }
    return () => {
      tokenSource = null
    }
  }, [isAuthenticated, loginWithRedirect, getAccessTokenSilently])

  const state: AuthState = {
    enabled: true,
    loading: isLoading,
    user: isAuthenticated && user ? { name: user.name, email: user.email, picture: user.picture } : null,
    login: () => void loginWithRedirect({ appState: { returnTo: returnTo() } }),
    logout: () => void logout({ logoutParams: { returnTo: location.origin + location.pathname } }),
  }
  return <AuthContext.Provider value={state}>{children}</AuthContext.Provider>
}

/** Wraps the app in Auth0 when the server publishes a login config; otherwise a no-op. */
export function AuthProvider({ config, children }: { config: AuthConfig | null | undefined; children: ReactNode }) {
  if (mockName()) return <MockAuthProvider>{children}</MockAuthProvider>
  if (!config) return <AuthContext.Provider value={disabled}>{children}</AuthContext.Provider>
  return (
    <Auth0Provider
      domain={config.domain}
      clientId={config.client_id}
      authorizationParams={{ redirect_uri: location.origin + location.pathname, audience: config.audience }}
      // Survives reloads without third-party cookies (Safari, Brave).
      cacheLocation="localstorage"
      useRefreshTokens
      onRedirectCallback={(appState) => {
        // The app routes on the hash; put it back and drop ?code=&state=.
        history.replaceState(null, '', location.pathname + (appState?.returnTo ?? '#/'))
        window.dispatchEvent(new HashChangeEvent('hashchange'))
      }}
    >
      <Bridge>{children}</Bridge>
    </Auth0Provider>
  )
}

function MockAuthProvider({ children }: { children: ReactNode }) {
  const [loggedIn, setLoggedIn] = useState(true)
  return <AuthContext.Provider value={{ enabled: true, loading: false, user: loggedIn ? { name: 'Preview user', email: 'preview@localhost' } : null, login: () => setLoggedIn(true), logout: () => setLoggedIn(false) }}>{children}</AuthContext.Provider>
}
